import itertools

def can_place_knights(n, board):
    if n > 64:
        return False
    for k in range(1, n // 2 + 1):
        for comb in itertools.combinations(range(n), k):
            if False in (board[i] == 1 and board[i + 1] == 1 or board[i] == 2 and board[i + 1] == 2) for i in comb:
                return False
    return True

def check_max_knights(n):
